// capital/lmsr.js — Phase 3: the LMSR market maker, ported from Pepe's pepe_amm.py expression for expression.
//
// Every float here must come out bit-for-bit what Python computes (test/capital-lmsr.test.js replays
// test/fixtures/capital-lmsr-vectors.json.gz, generated by camfrog-bot tools/gen_lmsr_vectors.py from the REAL Python code):
//   * sums run left to right from 0 in Python's dict order: q in the market's OPTIONS order (Pepe builds q from options),
//     a holder's cost / shares in the order the options were first traded, the holders in the order they first traded.
//     JavaScript objects put integer-like keys ("12345", "2") first, so the order is kept beside the record (m._ord) and
//     every loop walks it - never Object.keys();
//   * `x // y` on floats is Python's float floor division (fmod based), not Math.floor(x / y);
//   * int(x) truncates toward zero.
// Maths (logarithmic market scoring rule, liquidity b):
//   cost C(q) = b * ln( sum_i exp(q_i / b) );  price p_i = exp(q_i / b) / sum_j exp(q_j / b)
//   buying d shares of i costs C(q + d e_i) - C(q); selling gets C(q) - C(q - d e_i). The pot always equals C(q) (seeded
//   with C(0) = b ln n), and C(q) >= max_i q_i, so the pot can always pay every winning share.
"use strict";

const FD = require("./fdmath");          // exp / log identical to Pepe's pepe_fdmath.py (never Math.exp / Math.log)
const LIQUIDITY_B = 50000;
const FEE_PCT = 2;
const MIN_TRADE = 500;
const HISTORY_MAX = 400;
const EPS = 1e-9;

const int = (x) => Math.trunc(Number(x));

/** Python's float floor division (CPython float_floor_div / _float_div_mod). */
function pyFloorDiv(vx, wx) {
  vx = Number(vx); wx = Number(wx);
  let mod = vx % wx;                        // C fmod
  let div = (vx - mod) / wx;
  if (mod) {
    if ((wx < 0) !== (mod < 0)) { mod += wx; div -= 1.0; }
  }
  let floordiv;
  if (div) {
    floordiv = Math.floor(div);
    if (div - floordiv > 0.5) floordiv += 1.0;
  } else {
    floordiv = Math.sign(vx / wx) < 0 || Object.is(vx / wx, -0) ? -0 : 0;
  }
  return floordiv;
}
/** Python's integer floor division for ints (spend * 2 // 100). */
const idiv = (a, b) => Math.floor(a / b);

/** Python's round(x, 4) for display (history): correctly rounded half-even on the decimal value. */
function round4(x) {
  const n = Number(x);
  if (!Number.isFinite(n)) return n;
  return Number(n.toFixed(4)) === Number(Number(n.toPrecision(15)).toFixed(4)) ? Number(n.toFixed(4)) : Math.round(n * 1e4) / 1e4;
}

// ── order bookkeeping (Python dict insertion order) ──
function ord(m) {
  if (!m._ord || typeof m._ord !== "object") m._ord = {};
  const o = m._ord;
  if (!Array.isArray(o.pos)) o.pos = Object.keys(m.positions || {});
  if (!o.cost || typeof o.cost !== "object") o.cost = {};
  if (!o.shares || typeof o.shares !== "object") o.shares = {};
  return o;
}
function posKeys(m) {
  const o = ord(m);
  const have = m.positions || {};
  const keys = o.pos.filter((k) => Object.prototype.hasOwnProperty.call(have, k));
  for (const k of Object.keys(have)) if (!keys.includes(k)) keys.push(k);
  return keys;
}
function mapKeys(m, which, pk) {
  const o = ord(m);
  const map = ((m.positions || {})[pk] || {})[which] || {};
  const list = Array.isArray(o[which][pk]) ? o[which][pk] : [];
  const keys = list.filter((k) => Object.prototype.hasOwnProperty.call(map, k));
  for (const k of Object.keys(map)) if (!keys.includes(k)) keys.push(k);
  return keys;
}
function setIn(m, which, pk, opt, v) {
  const o = ord(m);
  const pos = m.positions[pk];
  if (!Object.prototype.hasOwnProperty.call(pos[which], opt)) {
    (o[which][pk] = Array.isArray(o[which][pk]) ? o[which][pk] : []).push(opt);
  }
  pos[which][opt] = v;
}
const getIn = (m, which, pk, opt) => {
  const map = ((m.positions || {})[pk] || {})[which] || {};
  return Object.prototype.hasOwnProperty.call(map, opt) ? Number(map[opt]) : 0.0;
};
/** The order of a holder's cost / shares dict (for an export back to Pepe). */
function sumIn(m, which, pk) {
  let s = 0;
  for (const k of mapKeys(m, which, pk)) s += Number(m.positions[pk][which][k]);
  return s;
}

// ── maths ──
function qVals(m, q) {
  q = q || m.q;
  return m.options.map((o) => Number(q[o] || 0));
}
function lse(b, vals) {
  let mx = vals[0];
  for (const v of vals) if (v > mx) mx = v;
  const m = mx / b;
  let s = 0;
  for (const v of vals) s += FD.exp(v / b - m);
  return b * (m + FD.log(s));
}
const cost = (m, q) => lse(Number(m.b), qVals(m, q));
function prices(m) {
  const b = Number(m.b);
  const vals = qVals(m);
  let mx = vals[0];
  for (const v of vals) if (v > mx) mx = v;
  mx = mx / b;
  const ex = vals.map((v) => FD.exp(v / b - mx));
  let s = 0;
  for (const e of ex) s += e;
  const out = {};
  m.options.forEach((o, i) => { out[o] = ex[i] / s; });
  return out;
}
/** Shares of `opt` that `net` PAT buys: d = b * ln(1 + S * (e^(c/b) - 1) / E_i). */
function sharesFor(m, opt, net) {
  const b = Number(m.b);
  const vals = qVals(m);
  let mx = vals[0];
  for (const v of vals) if (v > mx) mx = v;
  mx = mx / b;
  let S = 0;
  for (const v of vals) S += FD.exp(v / b - mx);
  const Ei = FD.exp(Number(m.q[opt]) / b - mx);
  return b * FD.log(1 + S * (FD.exp(net / b) - 1) / Ei);
}
function proceedsFor(m, opt, shares) {
  const q2 = Object.assign({}, m.q);
  q2[opt] = Number(q2[opt]) - shares;
  return cost(m) - cost(m, q2);
}
/** int(ceil(b * ln n)) + 1 - the pot a new market starts with. */
const seed = (n) => Math.trunc(Math.ceil(LIQUIDITY_B * FD.log(n))) + 1;

function newFields(m, nowS) {
  const b = LIQUIDITY_B;
  m.model = "lmsr";
  m.b = b;
  m.q = {};
  for (const o of m.options) m.q[o] = 0.0;
  m.pool = seed(m.options.length);
  m.seed = seed(m.options.length);
  m.positions = {};
  m.trades = [];
  m.volume = 0;
  m._ord = { pos: [], cost: {}, shares: {} };
  const p = prices(m);
  m.history = [[Math.trunc(nowS), Object.fromEntries(m.options.map((o) => [o, round4(p[o])]))]];
  return m;
}
function snapHistory(m, nowS) {
  const h = (m.history = Array.isArray(m.history) ? m.history : []);
  const p = prices(m);
  h.push([Math.trunc(nowS), Object.fromEntries(m.options.map((o) => [o, round4(p[o])]))]);
  if (h.length > HISTORY_MAX) h.splice(1, h.length - HISTORY_MAX);
}
/** _amm_pos: the holder's position (created on first use; its user filled in once known). */
function pos(m, nick, user) {
  const k = String(nick).toLowerCase();
  m.positions = m.positions || {};
  if (!Object.prototype.hasOwnProperty.call(m.positions, k)) {
    m.positions[k] = { nick, user: user || null, shares: {}, cost: {} };
    ord(m).pos.push(k);
  }
  const p = m.positions[k];
  if (user && !p.user) p.user = user;
  return k;
}

// ── trades (the market record only; the caller moves the PAT in the same transaction) ──
/** A buy of `spend` PAT on `opt`. -> {fee, net, shares} (m mutated exactly as _amm_buy_finish does). */
function applyBuy(m, { nick, user, opt, spend, nowS, web = null }) {
  spend = Math.trunc(Number(spend) || 0);
  const fee = idiv(spend * FEE_PCT, 100);
  const net = spend - fee;
  const shares = sharesFor(m, opt, net);
  m.q[opt] = Number(m.q[opt]) + shares;
  m.pool = Number(m.pool) + net;
  m.volume = int(m.volume || 0) + spend;
  const pk = pos(m, nick, user);
  setIn(m, "shares", pk, opt, getIn(m, "shares", pk, opt) + shares);
  setIn(m, "cost", pk, opt, getIn(m, "cost", pk, opt) + spend);
  m.trades = (m.trades || []).concat([{ ts: nowS, nick, side: "buy", option: opt, shares: Math.round(shares * 100) / 100, pat: spend, web }]).slice(-300);
  snapHistory(m, nowS);
  return { fee, net, shares };
}
/** The sell's numbers without changing anything. word = a share count or "all". -> {ok, error?, shares, gross, fee, pay, basis, held} */
function planSell(m, { nick, opt, want }) {
  const pk = String(nick).toLowerCase();
  const held = (m.positions || {})[pk] ? getIn(m, "shares", pk, opt) : 0.0;
  if (held <= EPS) return { ok: false, code: "no_shares", error: `you don't hold any ${opt} shares` };
  const all = ["all", "max", "everything"].includes(String(want).toLowerCase());
  const w = all ? held : Number(want) || 0;
  if (!(w > 0)) return { ok: false, code: "bad_amount", error: "say how many shares to sell, or 'all'" };
  const shares = held <= w ? held : w;            // Python min(held, want): the first when equal
  const gross = proceedsFor(m, opt, shares);
  const fee = int(pyFloorDiv(gross * FEE_PCT, 100));
  const pay = int(gross) - fee;
  const basis = getIn(m, "cost", pk, opt) * (shares / held);
  return { ok: true, pk, shares, gross, fee, pay, basis, held };
}
function applySell(m, plan, { nick, opt, nowS, web = null }) {
  const { pk, shares, gross, pay, basis, held } = plan;
  m.q[opt] = Number(m.q[opt]) - shares;
  m.pool = Number(m.pool) - int(gross);
  setIn(m, "shares", pk, opt, held - shares);
  setIn(m, "cost", pk, opt, getIn(m, "cost", pk, opt) - basis);
  m.volume = int(m.volume || 0) + int(gross);
  m.trades = (m.trades || []).concat([{ ts: nowS, nick, side: "sell", option: opt, shares: Math.round(shares * 100) / 100, pat: pay, web }]).slice(-300);
  snapHistory(m, nowS);
}
/**
 * _amm_resolve's payouts: 1 PAT per winning share; a void returns what holders put in net of the fee (cost x 0.98),
 * scaled down to what the pot holds above the seed. -> {payouts: [[nick, user, amount]], paid, leftover, pool}
 */
function resolvePlan(m, result) {
  const pool = Math.max(0.0, Number(m.pool));
  const keep = 1 - FEE_PCT / 100;
  const rows = [];
  for (const pk of posKeys(m)) {
    const p = m.positions[pk];
    const amt = result ? getIn(m, "shares", pk, result) : sumIn(m, "cost", pk) * keep;
    if (amt >= 1) rows.push([p.nick, p.user || null, amt]);
  }
  let total = 0;
  for (const r of rows) total += r[2];
  const avail = result ? pool : Math.max(0.0, pool - Number(m.seed || 0));
  if (total > avail && total > 0) {
    const scale = avail / total;
    for (const r of rows) r[2] *= scale;
  }
  const payouts = rows.map(([n, u, a]) => [n, u, int(a)]).filter((r) => r[2] > 0);
  const paid = payouts.reduce((t, r) => t + r[2], 0);
  return { payouts, paid, leftover: int(pool) - paid, pool };
}
/** pepe_vaults._vault_mm_book's value of one market: the pot minus the winning shares weighted by the market's prices. */
function mmValue(m) {
  try {
    const b = Number(m.b);
    const vals = qVals(m);
    let mx = vals[0];
    for (const v of vals) if (v > mx) mx = v;
    mx = mx / b;
    const ex = vals.map((v) => FD.exp(v / b - mx));
    let tot = 0;
    for (const e of ex) tot += e;
    let owed = 0;
    vals.forEach((v, i) => { owed += ex[i] / tot * v; });
    return Math.max(0.0, Number(m.pool || 0) - owed);
  } catch (e) {
    return Number(m.seed || 0);
  }
}

module.exports = { LIQUIDITY_B, FEE_PCT, MIN_TRADE, EPS, pyFloorDiv, idiv, round4, cost, prices, sharesFor, proceedsFor, seed, newFields,
                   snapHistory, pos, applyBuy, planSell, applySell, resolvePlan, mmValue, posKeys, mapKeys, sumIn, getIn, ord };
